function EXTRA(R,ICON){
 /* hook: a data sheet that quotes h parameters, and a line made of sections in a chain */
 ICON.ctSheet=(x,y)=>`<g transform="translate(${x-190} ${y-80})">${CT_box(0,0,380,160,{fill:'#FFFFFF',st:BLU,sw:3,r:18})}${CT_T(20,36,'transistor data sheet',{fs:24,fw:800,fill:BLU})}${CT_L(20,50,360,50,CT_AX,2)}${CT_T(24,90,`${CT_sub('h','11')}  1 kΩ`,{fs:26,fw:700})}${CT_T(24,136,`${CT_sub('h','21')}  50`,{fs:26,fw:700})}${CT_T(200,90,`${CT_sub('h','12')}  0.002`,{fs:26,fw:700})}${CT_T(200,136,`${CT_sub('h','22')}  20 μS`,{fs:26,fw:700})}</g>`;
 ICON.ctLine=(x,y)=>`<g transform="translate(${x-190} ${y-80})">${CT_box(0,0,380,160,{fill:'#FFFFFF',st:ORG,sw:3,r:18})}${CT_T(20,36,'a long line: a chain',{fs:24,fw:800,fill:ORG})}${CT_2p(46,62,70,56,'T₁',{L:14,fs:22,col:ORG,fill:'#FFF4E6'})}${CT_L(130,80,142,80,CT_INK,3)}${CT_L(130,100,142,100,CT_INK,3)}${CT_2p(156,62,70,56,'T₂',{L:14,fs:22,col:ORG,fill:'#FFF4E6'})}${CT_L(240,80,252,80,CT_INK,3)}${CT_L(240,100,252,100,CT_INK,3)}${CT_2p(266,62,70,56,'T₃',{L:14,fs:22,col:ORG,fill:'#FFF4E6'})}${CT_T(190,148,'[T] = [T₁][T₂][T₃]',{fs:22,fw:800,a:'middle',fill:CT_INK})}</g>`;
 /* recap pictures: each fills most of its card (about 420 × 330) */
 ICON.ctHm=(x,y)=>`<g transform="translate(${x-210} ${y-165})">${CT_term(10,60)}${CT_term(10,260)}${CT_res(16,160,60,BLU,4)}${CT_L(160,60,170,60,CT_INK,3)}${CT_L(170,60,170,122,CT_INK,3)}${CT_dia(170,160,38,GRN,'v')}${CT_L(170,198,170,260,CT_INK,3)}${CT_L(16,260,170,260,CT_INK,3)}${CT_T(88,36,'h₁₁',{fs:26,fw:800,a:'middle',fill:BLU})}${CT_T(124,170,'h₁₂V₂',{fs:24,fw:800,a:'end',fill:GRN})}
 ${CT_L(270,60,404,60,CT_INK,3)}${CT_L(270,260,404,260,CT_INK,3)}${CT_L(270,60,270,122,CT_INK,3)}${CT_L(270,198,270,260,CT_INK,3)}${CT_dia(270,160,38,GRN,'i')}${CT_resV(350,60,260,BLU,4)}${CT_dot(350,60)}${CT_dot(350,260)}${CT_term(410,60)}${CT_term(410,260)}${CT_T(372,168,'h₂₂',{fs:24,fw:800,fill:BLU})}${CT_T(210,316,'the transistor model',{fs:24,fw:700,a:'middle',fill:CT_MUT})}</g>`;
 ICON.ctChainI=(x,y)=>`<g transform="translate(${x-210} ${y-165})">${CT_2p(90,60,190,160,'ABCD',{L:60,fs:34,col:ORG,fill:'#FFF4E6'})}${CT_arrow(348,78,404,78,ORG,5)}${CT_T(376,56,'−I₂',{fs:30,fw:800,a:'middle',fill:ORG})}${CT_T(210,272,'open: A, C',{fs:26,fw:800,a:'middle',fill:BLU})}${CT_T(210,312,'shorted: B, D',{fs:26,fw:800,a:'middle',fill:GRN})}</g>`;
 ICON.ctCascade=(x,y)=>`<g transform="translate(${x-210} ${y-165})">${CT_arrow(20,40,400,40,GRN,4)}${CT_T(210,26,'signal',{fs:24,fw:800,a:'middle',fill:GRN})}${[0,1,2].map(i=>CT_2p(22+i*140,64,96,136,'T'+'₁₂₃'[i],{L:12,fs:34,col:GRN,fill:'#EBFBEE'})).join('')}${[130,270].map(xx=>CT_L(xx,82,xx+20,82,CT_INK,3)+CT_L(xx,182,xx+20,182,CT_INK,3)).join('')}${CT_T(210,258,'[T] = [T₁][T₂][T₃]',{fs:36,fw:800,a:'middle',fill:CT_INK})}${CT_T(210,302,'source side on the left',{fs:26,fw:700,a:'middle',fill:CT_MUT})}</g>`;
}
